var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
Debug.Log("[P] scene=" + scene.name + " path=" + scene.path);
string[] names = { "LowpolyTerrain", "Tree1", "Tree2", "Rock1", "Water" };
foreach (var n in names) {
  var gos = UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects();
  foreach (var g in gos) {
    var all = g.GetComponentsInChildren<Transform>(true);
    foreach (var t in all) {
      if (t.name == n) {
        var col = t.GetComponent<Collider>();
        Debug.Log("[P] found " + n + " layer=" + t.gameObject.layer + " (" + LayerMask.LayerToName(t.gameObject.layer) + ") col=" + (col == null ? "none" : col.GetType().Name) + " activeInHierarchy=" + t.gameObject.activeInHierarchy);
      }
    }
  }
}
var cams = UnityEngine.Object.FindObjectsOfType<Camera>(true);
foreach (var c in cams) Debug.Log("[P] camera " + c.name + " enabled=" + c.enabled + " mask=" + c.cullingMask + " (0x" + c.cullingMask.ToString("X8") + ")");
var lights = UnityEngine.Object.FindObjectsOfType<Light>(true);
foreach (var l in lights) if (l.type == LightType.Directional) Debug.Log("[P] dir light " + l.name + " mask=" + l.cullingMask + " (0x" + l.cullingMask.ToString("X8") + ")");
